// FUNCTION: BFME2 0x002326AE size=77 name=?getPrintableKey@Keyboard@@QAEGEH@Z evidence=N:ledger
unsigned short Keyboard::getPrintableKey(unsigned char key, int state)
{
    if (key >= KEY_NAMES_COUNT) return 0;
    if (state < 0 || state >= MAX_KEY_STATES) return 0;
    if (state == 0) return m_keyNames[key].stdKey;
    if (state == 1) return m_keyNames[key].shifted;
    return m_keyNames[key].shifted2;
}

// FUNCTION: BFME2 0x002326FB size=104 name=?createStreamMessages@Keyboard@@UAEXXZ evidence=N:ledger
void Keyboard::createStreamMessages()
{
	if (TheMessageStream == NULL)
		return;

	// Post a raw key message for every key record not yet consumed, then mark it.
	GameMessage *msg = NULL;
	KeyboardIO *last = m_keys.end();
	for (KeyboardIO *key = m_keys.begin(); key != last; ++key)
	{
		if (key->status == KeyboardIO::STATUS_USED)
			continue;

		if (key->state & KEY_STATE_DOWN)
			msg = TheMessageStream->appendMessage(GameMessage::MSG_RAW_KEY_DOWN);
		else if (key->state & KEY_STATE_UP)
			msg = TheMessageStream->appendMessage(GameMessage::MSG_RAW_KEY_UP);

		if (msg)
		{
			msg->appendIntegerArgument(key->key);
			msg->appendIntegerArgument(key->state);
		}
		key->status = KeyboardIO::STATUS_USED;
	}
}

