// FUNCTION: BFME2 0x002329D3 size=111 name=?checkKeyRepeat@Keyboard@@IAE_NXZ evidence=N:ledger
bool Keyboard::checkKeyRepeat()
{
	enum { KEY_REPEAT_DELAY = 10, NUM_KEYS = 256 };
	bool retVal = false;
	for (int key = 0; key < NUM_KEYS; ++key)
	{
		KeyboardIO *status = &m_keyStatus[key];
		if ((status->state & KEY_STATE_DOWN) == 0)
			continue;
		if ((unsigned)(m_inputFrame - status->sequence) <= KEY_REPEAT_DELAY)
			continue;
		KeyboardIO e;
		e.key = (unsigned char)key;
		e.state = KEY_STATE_DOWN | KEY_STATE_AUTOREPEAT;
		e.status = 0;
		m_keys.push_back(e);
		for (int index = 0; index < NUM_KEYS; ++index)
			m_keyStatus[index].sequence = m_inputFrame;
		m_keyStatus[key].sequence = m_inputFrame - (KEY_REPEAT_DELAY + 2);
		retVal = true;
		break;
	}
	return retVal;
}

// FUNCTION: BFME2 0x00232A42 size=166 name=?rva00232A42@Keyboard@@QAEXXZ evidence=?:placeholder
void Keyboard::rva00232A42()
{
	KeyboardIO *last = m_keys.end();
	for (KeyboardIO *rec = m_keys.begin(); rec != last; rec++)
	{
		m_keyStatus[rec->key].state = rec->state;
		m_keyStatus[rec->key].status = rec->status;
		m_keyStatus[rec->key].sequence = m_inputFrame;
		if (rec->key == 0x0F)
		{
			if ((m_keyStatus[0x38].state & 2) || (m_keyStatus[0xB8].state & 2))
				rec->status = 1;
		}
		else if (rec->key == 0x3A || rec->key == 0x1D || rec->key == 0x9D || rec->key == 0x2A || rec->key == 0x36 || rec->key == 0x38 || rec->key == 0xB8)
		{
			translateKey(rec->key);
		}
	}
	checkKeyRepeat();
	if (m_modifiers != 0)
	{
		KeyboardIO *stop = m_keys.end();
		for (KeyboardIO *rec = m_keys.begin(); rec != stop; rec++)
			rec->state |= m_modifiers;
	}
}

